import{_ as l,b as o,c as i,g as u}from"./chunks/framework.86O3EbG5.js";const d=JSON.parse('{"title":"知识图谱导论（六）","description":"","frontmatter":{"title":"知识图谱导论（六）","subTitle":"知识图谱融合","author":"oasis","date":"2026-03-04T00:00:00.000Z"},"headers":[],"relativePath":"articles/ai/books/knowledge-graph/6.md","filePath":"articles/ai/books/knowledge-graph/6.md"}'),e={name:"articles/ai/books/knowledge-graph/6.md"};function a(p,t,r,s,n,q){return o(),i("div",null,[...t[0]||(t[0]=[u('<p>知识图谱融合（Knowledge Graph Fusion）是指将多个来源、不同结构、不同描述粒度的知识图谱合并成一个更完整、更一致、更高质量的统一知识图谱的过程。</p><p>通俗地说：把多个&quot;知识碎片&quot;拼成一个完整的&quot;知识拼图&quot;。</p><h2 id="知识图谱融合的核心挑战" tabindex="-1">知识图谱融合的核心挑战</h2><ol><li>异构性挑战：不同知识图谱可能用完全不同的方式表示知识</li><li>质量挑战：A图谱中的可能正确，B 图谱中的可能错误</li></ol><p>知识图谱融合要解决的问题：</p><ol><li>实体对齐</li><li>概念对齐</li><li>属性融合</li><li>冲突解决</li></ol><p>看上去像解决 Git 冲突啊！想象有两个图书馆：</p><p>图书馆A（来自北京大学）：</p><ul><li>图书分类：按中图法（中国图书馆分类法）</li><li>作者姓名格式：&quot;姓, 名&quot;（如&quot;鲁迅&quot;标为&quot;周树人&quot;）</li><li>特色：中国现代文学收藏丰富</li></ul><p>图书馆B（来自哈佛大学）：</p><ul><li>图书分类：按LC分类法（美国国会图书馆分类法）</li><li>作者姓名格式：&quot;名 姓&quot;（如&quot;Lu Xun&quot;标为&quot;Xun Lu&quot;）</li><li>特色：海外汉学研究丰富</li></ul><p>现在，要把两个图书馆合并成一个统一的、更强大的图书馆。你会遇到什么问题？</p><ul><li>实体对齐：图书馆A的&quot;周树人&quot;和图书馆B的&quot;Xun Lu&quot;是不是同一个人？</li><li>概念对齐：中图法的&quot;I210&quot;类（鲁迅著作）和LC法的&quot;PL2754.S5&quot;类是不是同一主题？</li><li>属性融合：一个图书馆有作者生卒年，另一个有作者代表作，怎么合并？</li><li>冲突解决：两个图书馆对同一本书的出版年份记录不一致，以哪个为准？</li></ul>',13)])])}const c=l(e,[["render",a]]);export{d as __pageData,c as default};
